qs=prior['questions'];item={'key':'a_peu_pres','surfacePattern':phrase,'meaning':prior['meaning'],'sourceOccurrences':[{'chapter':6,'unit':unit,'start':start,'end':start+len(phrase),'text':phrase}],'componentTokens':[{k:t[k]for k in ['unit','start','end','text','form']}for t in tokens if t['unit']==unit and t['start']>=start and t['end']<=start+len(phrase)],'questions':qs,'questionSha256':h(qs),'identityTarget':'share_reviewed_earlier_full_expression','earlierFile':'chapter-05-expression-review.json','earlierKey':'a_peu_pres','earlierFileSha256':digest('chapter-05-expression-review.json'),'reviewNote':'Ou à peu près qualifies thinking as more or less, an approximation of the degree/description. The Chapter V full-span bank and all three bands were re-read: approximation rather than exact value, minimum or maximum. Share that meaning and bank; no new expression mastery duplication.','status':'offline_full_span_three_band_review_recorded_unpublished'};items.append(item)
