record={**common,'status':'offline_full_span_expression_questions_reviewed_unpublished','summary':{'reviewedExpressionForms':len(items),'reviewedQuestionBands':len(items)*3,'newQuestionBands':(len(items)-1)*3,'reusedEarlierQuestionBands':3,'sourcePhraseUses':sum(len(i['sourceOccurrences'])for i in items)},'items':items}
