progress['effectiveSummary']={**base['summary'],'reviewedUses':base['summary']['reviewedUses']+len(resolved),'reviewedExpressionComponentUses':len(resolved),'heldUses':len(left),'reviewedExpressionForms':len(items),'reviewedExpressionQuestionBands':len(items)*3}
progress['nextAction']['reason']='Earliest unresolved shared repair dependency. Next active lexical form: examiner, unit 138 offsets 151–159. Remaining held work includes qu’auraient at 134:222, avez auxiliary banks, relational pour, and comment capitalization impact review. Existing shared repairs stay deferred to complete-work reconciliation.'
